document.addEventListener('change',async e=>{if(e.target.id==='audio-speed-select'){audioPlaybackRate=Number(e.target.value)||1;document.querySelectorAll('audio').forEach(audio=>audio.playbackRate=audioPlaybackRate);return}if(e.target.id==='editor-audio-file'||e.target.id==='sync-audio-file'){const file=e.target.files?.[0];if(file){editorAudioFile=file;if(state.exerciseId.startsWith('custom-'))persistExerciseAudio(state.exerciseId,file).catch(()=>{});if(editorAudioUrl)URL.revokeObjectURL(editorAudioUrl);editorAudioUrl=URL.createObjectURL(file);if(state.exerciseId.startsWith('custom-'))practiceAudioByExercise.set(state.exerciseId,editorAudioUrl);const audio=document.querySelector('#editor-audio')||document.querySelector('#sync-audio');if(audio){audio.src=editorAudioUrl;audio.hidden=false;audio.playbackRate=audioPlaybackRate;audio.load()}const name=document.querySelector('#audio-file-name');if(name)name.textContent=file.name;updateSyncScreen()}}if(e.target.id==='note-display-select'){state.noteDisplay=e.target.value;localStorage.setItem('tabu-note-display',state.noteDisplay);render()}if(e.target.id==='exercise-select'){ stopPlayer();liveTracking=false;liveStatuses=[];state.step=0;state.exerciseId=e.target.value;state.bpm=currentExercise().bpm;practicePhase='idle';render();await restoreExerciseAudio(state.exerciseId)}});document.addEventListener('pointerdown',e=>{if(e.target.closest('#editor-fretboard .fretboard-svg'))editorPointerStart={id:e.pointerId,x:e.clientX,y:e.clientY}});document.addEventListener('pointercancel',()=>editorPointerStart=null);document.addEventListener('pointerup',e=>{const start=editorPointerStart;editorPointerStart=null;if(!start||start.id!==e.pointerId||Math.hypot(e.clientX-start.x,e.clientY-start.y)>10)return;const svg=e.target.closest('#editor-fretboard .fretboard-svg');if(!svg)return;const box=svg.getBoundingClientRect(),vb=svg.viewBox.baseVal,x=(e.clientX-box.left)*vb.width/box.width,y=(e.clientY-box.top)*vb.height/box.height,row=Math.round((y-48)/29);if(row<0||row>=strings.length)return;const fret=x<72?0:Math.min(22,Math.max(1,Math.round((x-95)/46)+1));appendEditorFret(strings[row],fret)});document.addEventListener('click',e=>{const syncItem=e.target.closest('[data-sync-index]');if(syncItem){const index=Number(syncItem.dataset.syncIndex);selectSyncNote(index);const note=editorSequence[index],audio=document.querySelector('#sync-audio');if(note&&Number.isFinite(note.startTime)&&audio)audio.currentTime=note.startTime;return}const syncNote=e.target.closest('#sync-fretboard .fret-note');if(syncNote){selectSyncNote(Number(syncNote.dataset.events.split(',')[0]));return}const route=e.target.closest('[data-route]');if(route){if(route.dataset.route==='editor'){editorEditingId=null;editorDraft=null}navigate(route.dataset.route);return}const action=e.target.closest('[data-action]');if(action)handleAction(action.dataset.action,action)});document.addEventListener('input',e=>{if(e.target.id==='tab-source'){state.editorText=e.target.value;const priorSequence=editorSequence;editorSequence=editorSequenceFromTab(e.target.value).map((note,index)=>({...note,startTime:priorSequence[index]?.string===note.string&&priorSequence[index]?.fret===note.fret?priorSequence[index].startTime:undefined,timeBeats:priorSequence[index]?.string===note.string&&priorSequence[index]?.fret===note.fret?priorSequence[index].timeBeats:undefined}));renderTab(document.querySelector('#editor-preview'),parseTab(e.target.value));const count=document.querySelector('#editor-sequence-count');if(count)count.textContent=`${editorSequence.length} nota · eklenme sırası`;refreshEditorBoard()}if(e.target.id==='slow-select')state.slow=Number(e.target.value)});document.addEventListener('keydown',e=>{if(syncMode&&e.code==='Space'){e.preventDefault();markSyncNow();return}if(syncMode&&e.key==='Backspace'){e.preventDefault();undoSyncMark();return}if((e.key==='Enter'||e.key===' ')&&e.target.matches('#editor-fretboard .fret-note')){e.preventDefault();appendEditorFret(e.target.dataset.string,Number(e.target.dataset.fret))}},true);window.addEventListener('hashchange',render);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;const btn=document.querySelector('#install-button');btn.hidden=false;btn.onclick=async()=>{deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null;btn.hidden=true}});window.addEventListener('load',()=>{if('serviceWorker'in navigator)navigator.serviceWorker.register('./service-worker.js').catch(console.error)});render();
